// mixedSatInertProbe answers zeros where Probe should act.
type mixedSatInertProbe struct{ poisonable.Mixed }

func (mixedSatInertProbe) Probe() (z0 error) {
	return
}

// mixedSatFlickerProbe answers zeros every second
// call, where Probe should answer the same thing twice.
//
// The defect every stability claim names: cacheable, deterministic,
// consistent, non-decreasing are all about two calls agreeing, and a subject
// that answers zeros *forever* agrees with itself perfectly. Only an answer
// that changes breaks them, and alternating with the zero is the smallest
// change available at any return type.
type mixedSatFlickerProbe struct {
	poisonable.Mixed
	flip atomic.Int64
}

func (m *mixedSatFlickerProbe) Probe() (z0 error) {
	if m.flip.Add(1)%2 == 0 {
		return
	}
	return m.Mixed.Probe()
}

// mixedSatSputterProbe alternates a minted refusal
// with the real answer where Probe should be steady.
type mixedSatSputterProbe struct {
	poisonable.Mixed
	flip atomic.Int64
}

func (m *mixedSatSputterProbe) Probe() (z0 error) {
	if m.flip.Add(1)%2 == 1 {
		z0 = errors.New("mixed: saturation sputtered a refusal")
		return
	}
	return m.Mixed.Probe()
}

// mixedSatStickProbe lets Probe work once
// and refuses forever after — the close that is not idempotent.
//
// sputter cannot express this. An idempotence law calls twice and discards
// the first answer, so an alternating refusal is absorbed by the very call
// the law is not reading, on every iteration. What the claim forbids is the
// *second* call failing, and only a defect that arrives after the first can
// say so.
type mixedSatStickProbe struct {
	poisonable.Mixed
	used atomic.Bool
}

func (m *mixedSatStickProbe) Probe() error {
	if m.used.Swap(true) {
		return errors.New("mixed: saturation stuck Probe after its first call")
	}
	return m.Mixed.Probe()
}

// mixedSatLatchProbe lets the first
// Probe through and quietly drops every one after it.
//
// The order-sensitive fold, which is the one defect a commutativity claim can
// see. That law builds both its instances from the same worn factory and
// applies the same values in opposite orders, so every other wear reaches
// both sides identically and the two observations agree however wrong they
// are. A fold that keeps only what it saw first keeps a different thing on
// each side.
//
// Silent, where stick refuses: a claim about what an operation *did* cannot
// be broken by one that says it failed.
type mixedSatLatchProbe struct {
	poisonable.Mixed
	used atomic.Bool
}

func (m *mixedSatLatchProbe) Probe() error {
	if m.used.Swap(true) {
		return nil
	}
	return m.Mixed.Probe()
}

